import json
import requests
import chardet
# Constants
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    if not isinstance(url, str) or not url:
        raise ValueError("Invalid URL provided.")

    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
        content = response.content
    except requests.RequestException as e:
        raise ValueError(f"Error fetching data from {url}: {e}")

    if not content:
        return {}

    encoding_result = chardet.detect(content)
    detected_encoding = encoding_result['encoding']

    if not detected_encoding:
        raise ValueError("Unable to detect encoding for non-empty content")

    try:
        decoded_content = content.decode(detected_encoding if from_encoding is None else from_encoding)
        re_encoded_content = decoded_content.encode(to_encoding)
        json_data = json.loads(re_encoded_content)
    except (UnicodeDecodeError, json.JSONDecodeError) as e:
        raise ValueError(f"Error decoding or parsing JSON: {e}")

    return json_data

